#!/usr/bin/env bash
# test-android.sh — the Android lane's tests.
#
#   scripts/test-android.sh                 # JVM unit tests: :core (fixtures, parser, engine) + :app
#   scripts/test-android.sh --instrumented  # also the on-device tests, on the running emulator
#   scripts/test-android.sh SharedFixtureEngineTests   # one class (bare names mean :core)
#
# The core suite is where the shared contract lives: it loads
# fixtures/conversion-cases.json (generated by the Swift core) and fails on any
# disagreement. It runs on the JVM in seconds — no emulator needed.
set -euo pipefail
source "$(dirname "$0")/lib/android-env.sh"
cd "$ANDROID_PROJECT_DIR"

INSTRUMENTED=false
TASKS=()
FILTER=()
for argument in "$@"; do
  case "$argument" in
    --instrumented) INSTRUMENTED=true ;;
    --help|-h) sed -n '2,10p' "$0"; exit 0 ;;
    *) FILTER=(--tests "*${argument}*") ;;
  esac
done

if [[ ${#FILTER[@]} -gt 0 ]]; then
  TASKS=(:core:test --rerun "${FILTER[@]}")
else
  # --rerun so a cached green run still prints its per-test lines.
  TASKS=(:core:test --rerun :app:testDebugUnitTest --rerun)
fi
$INSTRUMENTED && TASKS+=(:app:connectedDebugAndroidTest)

set -o pipefail
# PIPESTATUS must be read on the right of `||`: a trailing `|| true` followed
# by a separate assignment reads the status of `true`, and the script could
# never fail (found 2026-10-28 while templating this script into a skill).
GRADLE_EXIT=0
./gradlew "${TASKS[@]}" --console=plain 2>&1 | grep -E 'PASSED|FAILED|SKIPPED|BUILD|error:|e: ' \
  || GRADLE_EXIT=${PIPESTATUS[0]}
[[ $GRADLE_EXIT -eq 0 ]] || { echo "FAILED (gradle exit $GRADLE_EXIT)"; exit "$GRADLE_EXIT"; }
